def get_center_value(time_series):
    if not time_series:
        return None

    sorted_list = sorted(time_series)
    list_count = len(sorted_list)
    mid_index = list_count // 2

    if list_count % 2 == 1:
        return sorted_list[mid_index]
    else:
        return (sorted_list[mid_index - 1] + sorted_list[mid_index]) / 2
